// GetAll retrieves all matching documents
func (q *GreetingQuery) GetAll() DBOp[[]*Greeting] {
	return func(ctx context.Context) ([]*Greeting, error) {
		iter := q.query.Documents(ctx)
		defer iter.Stop()
		var results []*Greeting
		for {
			snap, err := iter.Next()
			if err == iterator.Done {
				break
			}
			if err != nil {
				return nil, err
			}
			var item Greeting
			if err := snap.DataTo(&item); err != nil {
				return nil, err
			}
			results = append(results, &item)
		}
		return results, nil
	}
}

// First retrieves the first matching document
func (q *GreetingQuery) First() DBOp[*Greeting] {
	return func(ctx context.Context) (*Greeting, error) {
		iter := q.query.Limit(1).Documents(ctx)
		defer iter.Stop()
		snap, err := iter.Next()
		if err == iterator.Done {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		var item Greeting
		if err := snap.DataTo(&item); err != nil {
			return nil, err
		}
		return &item, nil
	}
}

// Count returns the number of matching documents
func (q *GreetingQuery) Count() DBOp[int64] {
	return func(ctx context.Context) (int64, error) {
		agg, err := q.query.NewAggregationQuery().WithCount("count").Get(ctx)
		if err != nil {
			return 0, err
		}
		count, ok := agg["count"]
		if !ok {
			return 0, nil
		}
		if v, ok := count.(*int64); ok {
			return *v, nil
		}
		if v, ok := count.(int64); ok {
			return v, nil
		}
		return 0, nil
	}
}

// GetAll retrieves all documents in the collection
func (c *GreetingCollection) GetAll() DBOp[[]*Greeting] {
	return func(ctx context.Context) ([]*Greeting, error) {
		iter := c.client.Collection(c.path).Documents(ctx)
		defer iter.Stop()
		var results []*Greeting
		for {
			snap, err := iter.Next()
			if err == iterator.Done {
				break
			}
			if err != nil {
				return nil, err
			}
			var item Greeting
			if err := snap.DataTo(&item); err != nil {
				return nil, err
			}
			results = append(results, &item)
		}
		return results, nil
	}
}

// --- Greeting Batch Operations ---

// BatchSet sets multiple documents in a batch
func (c *GreetingCollection) BatchSet(items map[string]*Greeting) DBOp[bool] {
	return func(ctx context.Context) (bool, error) {
		batch := c.client.Batch()
		for id, item := range items {
			ref := c.client.Collection(c.path).Doc(id)
			batch.Set(ref, item)
		}
		_, err := batch.Commit(ctx)
		return err == nil, err
	}
}

// BatchDelete deletes multiple documents in a batch
func (c *GreetingCollection) BatchDelete(ids []string) DBOp[bool] {
	return func(ctx context.Context) (bool, error) {
		batch := c.client.Batch()
		for _, id := range ids {
			ref := c.client.Collection(c.path).Doc(id)
			batch.Delete(ref)
		}
		_, err := batch.Commit(ctx)
		return err == nil, err
	}
}

// GetMultiple retrieves multiple documents by ID
func (c *GreetingCollection) GetMultiple(ids []string) DBOp[[]*Greeting] {
	return TraverseDBOp(ids, func(id string) DBOp[*Greeting] {
		return c.Doc(id).Get()
	})
}

// GetMultipleParallel retrieves multiple documents in parallel
func (c *GreetingCollection) GetMultipleParallel(ids []string) DBOp[[]*Greeting] {
	return TraverseParallelDBOp(ids, func(id string) DBOp[*Greeting] {
		return c.Doc(id).Get()
	})
}

// --- Greeting Subcollection Support ---

// Subcollection returns a collection nested under a document (requires context for tenant scoping)
func (d *GreetingDoc) Subcollection(ctx context.Context, name string) *firestore.CollectionRef {
	return d.resolveDocRef(ctx).Collection(name)
}

// --- HelloService ---

// HelloServiceK represents the service as Kleisli arrows
type HelloServiceK struct {
	SayHello      func(*SayHelloRequest) NetworkOp[*SayHelloResponse]
	ListGreetings func(*ListGreetingsRequest) NetworkOp[*ListGreetingsResponse]
}

// HelloServiceSayHelloAndThen chains SayHello with another effectful function
func HelloServiceSayHelloAndThen[B any](s *HelloServiceK, f func(*SayHelloResponse) NetworkOp[B]) func(*SayHelloRequest) NetworkOp[B] {
	return ComposeKleisliNetworkOp(s.SayHello, f)
}

// HelloServiceListGreetingsAndThen chains ListGreetings with another effectful function
func HelloServiceListGreetingsAndThen[B any](s *HelloServiceK, f func(*ListGreetingsResponse) NetworkOp[B]) func(*ListGreetingsRequest) NetworkOp[B] {
	return ComposeKleisliNetworkOp(s.ListGreetings, f)
}

// HelloServiceMiddleware wraps service methods
type HelloServiceMiddleware struct {
	SayHello      func(func(*SayHelloRequest) NetworkOp[*SayHelloResponse]) func(*SayHelloRequest) NetworkOp[*SayHelloResponse]
	ListGreetings func(func(*ListGreetingsRequest) NetworkOp[*ListGreetingsResponse]) func(*ListGreetingsRequest) NetworkOp[*ListGreetingsResponse]
}

// ApplyHelloServiceMiddleware applies middleware to a service
func ApplyHelloServiceMiddleware(s *HelloServiceK, mw *HelloServiceMiddleware) *HelloServiceK {
	result := &HelloServiceK{}
	if mw.SayHello != nil {
		result.SayHello = mw.SayHello(s.SayHello)
	} else {
		result.SayHello = s.SayHello
	}
	if mw.ListGreetings != nil {
		result.ListGreetings = mw.ListGreetings(s.ListGreetings)
	} else {
		result.ListGreetings = s.ListGreetings
	}
	return result
}

// MockHelloServiceK creates a mock implementation
type MockHelloServiceK struct {
	SayHelloFunc       func(*SayHelloRequest) NetworkOp[*SayHelloResponse]
	SayHelloCalls      []*SayHelloRequest
	ListGreetingsFunc  func(*ListGreetingsRequest) NetworkOp[*ListGreetingsResponse]
	ListGreetingsCalls []*ListGreetingsRequest
}

// NewMockHelloServiceK creates a new mock
func NewMockHelloServiceK() *MockHelloServiceK {
	return &MockHelloServiceK{}
}

// SayHello records the call and delegates to the mock function
func (m *MockHelloServiceK) SayHello(req *SayHelloRequest) NetworkOp[*SayHelloResponse] {
	m.SayHelloCalls = append(m.SayHelloCalls, req)
	if m.SayHelloFunc != nil {
		return m.SayHelloFunc(req)
	}
	return PureNetworkOp[*SayHelloResponse](nil)
}

// ListGreetings records the call and delegates to the mock function
func (m *MockHelloServiceK) ListGreetings(req *ListGreetingsRequest) NetworkOp[*ListGreetingsResponse] {
	m.ListGreetingsCalls = append(m.ListGreetingsCalls, req)
	if m.ListGreetingsFunc != nil {
		return m.ListGreetingsFunc(req)
	}
	return PureNetworkOp[*ListGreetingsResponse](nil)
}

// ToKleisli converts mock to Kleisli service
func (m *MockHelloServiceK) ToKleisli() *HelloServiceK {
	return &HelloServiceK{
		SayHello:      m.SayHello,
		ListGreetings: m.ListGreetings,
	}
}

// --- HelloService Connect Bridge ---

// Connect bridge requires: connectrpc.com/connect
// Import the generated connect package for your service

// HelloServiceConnectClient interface mirrors connect-go generated client
type HelloServiceConnectClient interface {
	SayHello(context.Context, *connect.Request[SayHelloRequest]) (*connect.Response[SayHelloResponse], error)
	ListGreetings(context.Context, *connect.Request[ListGreetingsRequest]) (*connect.Response[ListGreetingsResponse], error)
}

// NewHelloServiceKFromConnect wraps a Connect client as Kleisli arrows
func NewHelloServiceKFromConnect(client HelloServiceConnectClient) *HelloServiceK {
	return &HelloServiceK{
		SayHello: func(req *SayHelloRequest) NetworkOp[*SayHelloResponse] {
			return func(ctx context.Context) (*SayHelloResponse, error) {
				resp, err := client.SayHello(ctx, connect.NewRequest(req))
				if err != nil {
					return nil, err
				}
				return resp.Msg, nil
			}
		},
		ListGreetings: func(req *ListGreetingsRequest) NetworkOp[*ListGreetingsResponse] {
			return func(ctx context.Context) (*ListGreetingsResponse, error) {
				resp, err := client.ListGreetings(ctx, connect.NewRequest(req))
				if err != nil {
					return nil, err
				}
				return resp.Msg, nil
			}
		},
	}
}

// HelloServiceConnectHandler implements Connect handler using Kleisli service
type HelloServiceConnectHandler struct {
	svc *HelloServiceK
}

// NewHelloServiceConnectHandler creates a Connect handler from Kleisli service
func NewHelloServiceConnectHandler(svc *HelloServiceK) *HelloServiceConnectHandler {
	return &HelloServiceConnectHandler{svc: svc}
}

// SayHello implements helloserviceconnect.HelloServiceHandler
func (h *HelloServiceConnectHandler) SayHello(
	ctx context.Context,
	req *connect.Request[SayHelloRequest],
) (*connect.Response[SayHelloResponse], error) {
	result, err := h.svc.SayHello(req.Msg)(ctx)
	if err != nil {
		return nil, err
	}
	return connect.NewResponse(result), nil
}

// ListGreetings implements helloserviceconnect.HelloServiceHandler
func (h *HelloServiceConnectHandler) ListGreetings(
	ctx context.Context,
	req *connect.Request[ListGreetingsRequest],
) (*connect.Response[ListGreetingsResponse], error) {
	result, err := h.svc.ListGreetings(req.Msg)(ctx)
	if err != nil {
		return nil, err
	}
	return connect.NewResponse(result), nil
}

// NewHelloServiceKFromConnectWithDefaults wraps Connect client with retry and timeout
func NewHelloServiceKFromConnectWithDefaults(
	client HelloServiceConnectClient,
	timeout time.Duration,
	maxRetries int,
) *HelloServiceK {
	base := NewHelloServiceKFromConnect(client)
	return &HelloServiceK{
		SayHello: func(req *SayHelloRequest) NetworkOp[*SayHelloResponse] {
			return TimeoutNetworkOp(
				RetryNetworkOp(base.SayHello(req), maxRetries, 100*time.Millisecond, 2*time.Second),
				timeout,
			)
		},
		ListGreetings: func(req *ListGreetingsRequest) NetworkOp[*ListGreetingsResponse] {
			return TimeoutNetworkOp(
				RetryNetworkOp(base.ListGreetings(req), maxRetries, 100*time.Millisecond, 2*time.Second),
				timeout,
			)
		},
	}
}
